'use strict';
// Explicit manual experiment. Never imported by production or the test suite.
const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),cp=require('node:child_process'),crypto=require('node:crypto');
const {planSegments}=require('../../planning/flv-segment-plan');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const reuse=process.argv[2];
if(reuse&&!/^MontClip-segment-media-[A-Za-z0-9]+$/.test(reuse))throw Error('INVALID_REUSE');
const root=reuse?path.join(os.tmpdir(),reuse):fs.mkdtempSync(path.join(os.tmpdir(),'MontClip-segment-media-'));
const commands=[];
function run(tool,args){const r=cp.spawnSync(tool,args,{encoding:'utf8',timeout:60000,maxBuffer:4*1024*1024,windowsHide:true});commands.push({tool,args:args.map(s=>s.split(root).join('<fixture>')),exit:r.status,stderr:(r.stderr||'').slice(-4096).split(root).join('<fixture>')});if(r.status!==0)throw Error(tool+':'+r.status);return r.stdout;}
function probe(file){return JSON.parse(run('ffprobe',['-v','error','-show_frames','-show_streams','-of','json',file]));}
function sums(file,type){let out;try{out=run('ffmpeg',['-v','error','-i',file,'-map',type==='video'?'0:v:0':'0:a:0','-f','framemd5','-']);}catch(e){return [];}return out.split(/\r?\n/).filter(s=>s&&!s.startsWith('#')).map(s=>{const a=s.split(',').map(x=>x.trim());return {pts:Number(a[2]),duration:Number(a[3]),bytes:Number(a[4]),md5:a[5]};});}
function analyze(file){const p=probe(file),v=sums(file,'video'),a=sums(file,'audio');return {sha256:hash(fs.readFileSync(file)),bytes:fs.statSync(file).size,streams:p.streams.map(s=>({index:s.index,type:s.codec_type,timeBase:s.time_base,start:s.start_time})),video:p.frames.filter(f=>f.media_type==='video').map((f,i)=>({pts:Number(f.best_effort_timestamp_time),duration:Number(f.duration_time||f.pkt_duration_time),key:f.key_frame,kind:f.pict_type,md5:v[i]?.md5})),audio:p.frames.filter(f=>f.media_type==='audio').map((f,i)=>({pts:Number(f.best_effort_timestamp_time),duration:Number(f.duration_time||f.pkt_duration_time),samples:f.nb_samples,md5:a[i]?.md5})),decoded:{video:v,audio:a}};}
function main(){const stat=fs.statfsSync(root);if(stat.bavail*stat.bsize<10*1024**3+64*1024**2)throw Error('SPACE_RESERVE');const report={platform:process.platform,node:process.version,freeBefore:stat.bavail*stat.bsize,commands,cases:[]};
for(const tool of ['ffmpeg','ffprobe']){const exe=run('where.exe',[tool]).trim().split(/\r?\n/)[0];report[tool]={version:run(tool,['-version']).split(/\r?\n/)[0],exeSha256:hash(fs.readFileSync(exe))};}
for(const gop of [10,40]){const source=path.join(root,'gop'+gop+'.flv');if(!reuse)run('ffmpeg',['-v','error','-n','-f','lavfi','-i','testsrc2=size=160x96:rate=10:duration=4','-f','lavfi','-i','aevalsrc=sin(2*PI*(300*t+50*t*t)):s=48000:d=4','-vf','setpts=PTS+2/TB+gte(T\\,2)*0.5/TB','-af','asetpts=PTS+2/TB+gte(T\\,2)*0.5/TB','-fps_mode','passthrough','-c:v','libx264','-preset','ultrafast','-crf','18','-g',String(gop),'-keyint_min',String(gop),'-sc_threshold','0','-bf','0','-c:a','aac','-b:a','96k','-copyts','-f','flv',source]);const src=analyze(source);const record={gop,source:src,outputs:[]};report.cases.push(record);
const units=type=>src[type].map((u,i)=>({id:type+i,pts:Math.round(u.pts*1000),duration:Math.round(u.duration*1000)}));record.plan=planSegments({sourceId:'gop'+gop,sourceHash:src.sha256,ticksPerSecond:1000,video:units('video'),audio:units('audio')});
for(const [name,start,end] of [['left',2,4],['right',4.5,6.5]]){const out=path.join(root,'gop'+gop+'-'+name+'.mkv');if(!reuse)run('ffmpeg',['-v','error','-n','-copyts','-i',source,'-ss',String(start),'-to',String(end),'-map','0:v:0','-map','0:a:0','-c','copy',out]);const result=analyze(out);const mapping={};for(const type of ['video','audio']){const expected=src[type].filter(u=>u.pts>=start&&u.pts+u.duration<=end+1e-9);const actual=result[type];mapping[type]={expectedCount:expected.length,actualCount:actual.length,exactOrderedHashes:JSON.stringify(expected.map(u=>u.md5))===JSON.stringify(actual.map(u=>u.md5)),crossingSourceUnits:src[type].filter(u=>(u.pts<start&&u.pts+u.duration>start)||(u.pts<end&&u.pts+u.duration>end)),observed:actual.map(u=>({outputPts:u.pts,sourceMatches:src[type].filter(s=>s.md5===u.md5).map(s=>s.pts)}))};}record.outputs.push({name,start,end,result,mapping,accepted:false});}}
report.freeAfter=fs.statfsSync(root).bavail*fs.statfsSync(root).bsize;report.ownedBytes=fs.readdirSync(root).reduce((n,f)=>n+fs.statSync(path.join(root,f)).size,0);fs.writeFileSync('docs/validation/2026-11-01-flv-segment-media.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({retainedDirectory:path.basename(root),ownedBytes:report.ownedBytes,cases:report.cases.map(c=>({gop:c.gop,plan:c.plan,outputs:c.outputs.map(o=>({name:o.name,video:o.mapping.video.exactOrderedHashes,audio:o.mapping.audio.exactOrderedHashes,counts:[o.mapping.video.expectedCount,o.mapping.video.actualCount]}))}))}));}
try{main();}catch(e){fs.writeFileSync('docs/validation/2026-11-01-flv-segment-media-failure.json',JSON.stringify({error:e.message,commands},null,2));console.error(e.message);console.error('retained task directory: '+path.basename(root));process.exitCode=1;}
